#!/usr/bin/env python3
"""Writes customizations_texts.h from the Electron build's src/dev/custom.js.

  chromium/tools/gen_custom_texts.py <custom.js> <customizations_texts.h>

The starter files of the Workbench customization folder (user.css, the
example plugin, API.md, AGENTS.md, CLAUDE.md, settings.json) as C++ raw
strings, word for word.
"""
import json
import subprocess
import sys

HEADER = '''// Copyright 2026 The Meridian Authors
// Use of this source code is governed by a BSD-style license that can be
// found in the LICENSE file.

// Generated by chromium/tools/gen_custom_texts.py from src/dev/custom.js.

#ifndef CHROME_BROWSER_MERIDIAN_WORKBENCH_CUSTOMIZATIONS_TEXTS_H_
#define CHROME_BROWSER_MERIDIAN_WORKBENCH_CUSTOMIZATIONS_TEXTS_H_

namespace meridian::workbench::texts {

'''
FOOTER = '''
}  // namespace meridian::workbench::texts

#endif  // CHROME_BROWSER_MERIDIAN_WORKBENCH_CUSTOMIZATIONS_TEXTS_H_
'''


def main():
  # The strings exactly as JavaScript sees them (template literals evaluated).
  script = open(sys.argv[1], encoding='utf-8').read() + (
      '\nmodule.exports = { USER_CSS, EXAMPLE_PLUGIN, API_MD, AGENTS_MD, '
      'CLAUDE_MD, DEFAULT_SETTINGS };\n')
  out = subprocess.run(
      ['node', '-e',
       'const m = new module.constructor(); m.paths = module.paths; '
       'm._compile(require("fs").readFileSync(0, "utf8"), "custom.js"); '
       'process.stdout.write(JSON.stringify(m.exports));'],
      input=script, capture_output=True, text=True, check=True).stdout
  t = json.loads(out)
  values = {
      'kUserCss': t['USER_CSS'],
      'kExamplePlugin': t['EXAMPLE_PLUGIN'],
      'kApiMd': t['API_MD'],
      'kAgentsMd': t['AGENTS_MD'],
      'kClaudeMd': t['CLAUDE_MD'],
      'kDefaultSettings': json.dumps(t['DEFAULT_SETTINGS'], indent=2) + '\n',
  }
  out = [HEADER]
  for name, text in values.items():
    assert ')meridian"' not in text
    out.append('inline constexpr char %s[] = R"meridian(%s)meridian";\n\n' %
               (name, text))
  open(sys.argv[2], 'w', encoding='utf-8').write(''.join(out) + FOOTER)


main()
